package career.assistant.application.service;
import career.assistant.api.ResourceNotFoundException; import career.assistant.application.ats.*; import career.assistant.application.entity.*; import career.assistant.application.repository.ApplicationRepository; import career.assistant.document.service.*; import career.assistant.company.repository.CompanyRepository; import career.assistant.job.entity.Job; import career.assistant.job.service.JobService; import career.assistant.jobscore.entity.JobScore; import career.assistant.jobscore.service.JobScoringService; import org.springframework.beans.factory.annotation.Value; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.math.BigDecimal; import java.net.URI; import java.time.*; import java.util.*;
@Service public class ApplicationWorkflowService {
 private final ApplicationRepository apps; private final JobService jobs; private final JobScoringService scoring; private final ResumeService resumes; private final CoverLetterService letters; private final CompanyRepository companies; private final PublicAtsAdapters adapters; private final ApplicationNotificationService mail;
 private final boolean enabled,dryRun; private final int dailyLimit; private final Set<String> allowlist;
 public ApplicationWorkflowService(ApplicationRepository a,JobService j,JobScoringService s,ResumeService r,CoverLetterService l,CompanyRepository c,PublicAtsAdapters ad,ApplicationNotificationService m,@Value("${career.application.auto-apply-enabled:false}")boolean e,@Value("${career.application.dry-run:true}")boolean d,@Value("${career.application.max-real-submissions-daily:3}")int limit,@Value("${career.application.allowlisted-domains:}")String domains){apps=a;jobs=j;scoring=s;resumes=r;letters=l;companies=c;adapters=ad;mail=m;enabled=e;dryRun=d;dailyLimit=limit;allowlist=new HashSet<>(Arrays.stream(domains.split(",")).map(String::trim).map(String::toLowerCase).filter(x->!x.isBlank()).toList());}
 @Transactional public WorkflowResponse generate(UUID jobId,boolean lowConfidenceConfirmed){Job job=jobs.findRequired(jobId);JobScore score=scoring.findOrScore(job);String confidence=confidence(score);if("LOW".equals(confidence)&&!lowConfidenceConfirmed)throw new ResumeConflictException("LOW-confidence jobs require explicit manual confirmation before generation");Application existing=apps.findByJobId(jobId).orElse(null);if(existing!=null&&existing.getResumeVersionId()!=null&&existing.getCoverLetterId()!=null)return response(existing,job,score);
  var resume=resumes.createCustomized(jobId);var letter=letters.generate(job);Application a=existing==null?new Application():existing;a.setJob(job);a.setStatus(ApplicationStatus.PENDING_REVIEW);a.setApplicationType(ApplicationType.MANUAL);a.setApplicationUrl(job.getJobUrl());a.setResumeVersionId(resume.id());a.setCoverLetterId(letter.getId());a.setIdempotencyKey("job:"+jobId);adapters.resolve(job.getJobUrl()).ifPresent(adapter->a.setAdapter(adapter.name()));a.setErrorMessage(eligibility(job,score,a).reason());job.setStatus("PENDING_REVIEW");return response(apps.save(a),job,score);}
 @Transactional public WorkflowResponse review(UUID id,boolean approve,String reason){Application a=required(id);if(a.getResumeVersionId()==null||a.getCoverLetterId()==null)throw new ResumeConflictException("A complete document package is required");a.setStatus(approve?ApplicationStatus.READY_TO_APPLY:ApplicationStatus.REJECTED);a.setReviewedAt(OffsetDateTime.now());a.setNotes(reason);a.setErrorMessage(null);a.getJob().setStatus(a.getStatus().name());JobScore score=scoring.findOrScore(a.getJob());return response(apps.save(a),a.getJob(),score);}
 @Transactional public WorkflowResponse returnToReview(UUID id,String reason){Application a=required(id);a.setStatus(ApplicationStatus.PENDING_REVIEW);a.getJob().setStatus(ApplicationStatus.PENDING_REVIEW.name());a.setNotes(reason);a.setErrorMessage(null);return response(apps.save(a),a.getJob(),scoring.findOrScore(a.getJob()));}
 @Transactional public WorkflowResponse markManuallyApplied(UUID id,boolean confirmed,String confirmation){if(!confirmed)throw new ResumeConflictException("Explicit confirmation is required before marking an application as manually applied");Application a=required(id);if(a.getStatus()!=ApplicationStatus.READY_TO_APPLY)throw new ResumeConflictException("Only a reviewed Ready to Apply application can be marked manually applied");if(a.getResumeVersionId()==null||a.getCoverLetterId()==null)throw new ResumeConflictException("A complete document package is required");OffsetDateTime now=OffsetDateTime.now();a.setStatus(ApplicationStatus.MANUALLY_APPLIED);a.getJob().setStatus(ApplicationStatus.MANUALLY_APPLIED.name());a.setAppliedAt(now);a.setSubmittedAt(now);a.setConfirmationId(confirmation==null||confirmation.isBlank()?"MANUAL":confirmation.trim());a.setErrorMessage(null);JobScore score=scoring.findOrScore(a.getJob());Application saved=apps.save(a);mail.sendVerifiedSuccessOnce(saved,String.valueOf(score.getScore()));return response(saved,a.getJob(),score);}
 @Transactional public WorkflowResponse run(UUID id){Application a=required(id);Job j=a.getJob();JobScore score=scoring.findOrScore(j);Eligibility gate=eligibility(j,score,a);if(!gate.eligible()){a.setStatus(ApplicationStatus.PENDING_REVIEW);j.setStatus(ApplicationStatus.PENDING_REVIEW.name());a.setErrorMessage(gate.reason());return response(apps.save(a),j,score);}var adapter=adapters.resolve(j.getJobUrl());if(adapter.isEmpty()){a.setStatus(ApplicationStatus.PENDING_REVIEW);j.setStatus(ApplicationStatus.PENDING_REVIEW.name());a.setErrorMessage(PublicAtsAdapters.unsupportedReason(j.getJobUrl()));return response(apps.save(a),j,score);}a.setAdapter(adapter.get().name());if(dryRun||!enabled){var result=adapter.get().dryRun(j,a);a.setStatus(ApplicationStatus.READY_TO_APPLY);j.setStatus(ApplicationStatus.READY_TO_APPLY.name());a.setErrorMessage(result.reason());return response(apps.save(a),j,score);}a.setStatus(ApplicationStatus.PENDING_REVIEW);j.setStatus(ApplicationStatus.PENDING_REVIEW.name());a.setErrorMessage("Real submission blocked: mandatory legal, visa, sponsorship, and salary answers are unset; values will never be invented.");return response(apps.save(a),j,score);}
 @Transactional public List<WorkflowResponse> list(){return apps.findAll().stream().map(a->response(a,a.getJob(),scoring.findOrScore(a.getJob()))).toList();}
 private Eligibility eligibility(Job j,JobScore s,Application a){List<String> reasons=new ArrayList<>();if(s.getScore()==null||s.getScore().compareTo(new BigDecimal("90"))<0)reasons.add("score below 90");if(!"HIGH".equals(confidence(s)))reasons.add("confidence is not HIGH");String location=(String.valueOf(j.getLocation())+" "+String.valueOf(j.getCountry())).toLowerCase();if(!(location.contains("uae")||location.contains("united arab emirates")||location.contains("dubai")||location.contains("abu dhabi")||location.contains("sharjah")))reasons.add("location is not explicitly UAE");if(j.getExperienceMin()==null||j.getExperienceMax()==null||j.getExperienceMax()<4||j.getExperienceMin()>8)reasons.add("experience is not confirmed compatible with 4–8 years");if(s.getRequiredSkillsScore()==null||s.getRequiredSkillsScore().compareTo(new BigDecimal("100"))<0)reasons.add("required skills are missing or unknown");if(resumes.activeMasterEntity().isEmpty())reasons.add("no active verified master resume");if(a.getResumeVersionId()==null||a.getCoverLetterId()==null)reasons.add("document package is incomplete");String host=host(j.getJobUrl());if(!allowlist.contains(host))reasons.add("domain is not allowlisted");if(a.getStatus()==ApplicationStatus.AUTO_APPLIED||a.getStatus()==ApplicationStatus.MANUALLY_APPLIED)reasons.add("job was already submitted");OffsetDateTime start=LocalDate.now(ZoneOffset.UTC).atStartOfDay().atOffset(ZoneOffset.UTC);if(apps.countByStatusAndAppliedAtBetween(ApplicationStatus.AUTO_APPLIED,start,start.plusDays(1))>=dailyLimit)reasons.add("daily real-submission limit reached");return new Eligibility(reasons.isEmpty(),String.join("; ",reasons));}
 private WorkflowResponse response(Application a,Job j,JobScore s){String company=companies.findById(j.getCompanyId()).map(c->c.getName()).orElse("Unknown company");var adapter=adapters.resolve(j.getJobUrl());List<String> required=adapter.map(value->value.requiredFields(j).stream().filter(AtsAdapter.FormField::required).map(AtsAdapter.FormField::name).toList()).orElse(List.of());Set<String> verified=required.isEmpty()?Set.of():verifiedApplicationAnswers(a);List<String> missing=required.stream().filter(field->!verified.contains(field)).toList();return new WorkflowResponse(a.getId(),j.getId(),j.getTitle(),company,j.getJobUrl(),s.getScore(),confidence(s),csv(s.getMatchedKeywords()),csv(s.getMissingKeywords()),s.getLocationScore(),s.getExperienceScore(),s.getScoringReason(),required,missing,a.getStatus(),a.getResumeVersionId(),a.getCoverLetterId(),a.getAdapter(),a.getConfirmationId(),a.getConfirmationUrl(),a.getErrorMessage()!=null?a.getErrorMessage():a.getNotes(),a.getAppliedAt(),a.getCreatedAt());}
 private Set<String> verifiedApplicationAnswers(Application a){Set<String> verified=new HashSet<>();resumes.activeMasterEntity().ifPresent(master->{var parsed=resumes.parsed(master);if(parsed!=null&&parsed.name()!=null&&!parsed.name().isBlank())verified.add("Name");String text=Optional.ofNullable(master.getParsedText()).orElse("");if(java.util.regex.Pattern.compile("\\b[A-Z0-9._%+-]+@[A-Z0-9.-]+\\.[A-Z]{2,}\\b",java.util.regex.Pattern.CASE_INSENSITIVE).matcher(text).find())verified.add("Email");if(java.util.regex.Pattern.compile("(?<!\\d)(?:\\+?\\d[\\d ()-]{7,}\\d)(?!\\d)").matcher(text).find())verified.add("Phone");});if(a.getResumeVersionId()!=null)verified.add("Resume");return verified;}
 private Application required(UUID id){return apps.findById(id).orElseThrow(()->new ResourceNotFoundException("Application not found"));}private static String confidence(JobScore s){if(s.getScoringConfidence()!=null)return s.getScoringConfidence();String r=s.getScoringReason();return r!=null&&r.contains("confidence HIGH")?"HIGH":"LOW";}private static List<String> csv(String s){return s==null||s.isBlank()?List.of():Arrays.stream(s.split(",")).map(String::trim).toList();}private static String host(String url){try{return Optional.ofNullable(URI.create(url).getHost()).orElse("").toLowerCase();}catch(Exception e){return "";}}
 private record Eligibility(boolean eligible,String reason){} public record WorkflowResponse(UUID id,UUID jobId,String job,String company,String sourceUrl,BigDecimal score,String confidence,List<String> matchedSkills,List<String> missingSkills,BigDecimal locationFit,BigDecimal experienceFit,String scoreExplanation,List<String> requiredFields,List<String> missingRequiredAnswers,ApplicationStatus status,UUID resumeVersionId,UUID coverLetterId,String adapter,String confirmationId,String confirmationUrl,String reason,OffsetDateTime appliedAt,OffsetDateTime createdAt){}
}
